mapper.select:
SELECT id, name, login_name, password, phone, department, workstation, role, create_time, update_time
FROM `user`
WHERE id = #{id}

SELECT id, name, login_name, password, phone, department, workstation, role, create_time, update_time
FROM `user`
WHERE login_name = #{loginName}

SELECT id, name, login_name, password, phone, department, workstation, role, create_time, update_time FROM `user`
AND (name LIKE CONCAT('%', #{keyword}, '%') OR login_name LIKE CONCAT('%', #{keyword}, '%'))
AND role = #{role}
AND department LIKE CONCAT('%', #{department}, '%')
ORDER BY id DESC LIMIT #{offset}, #{size}
